-- GI-COMMON-CRM canonical tenant-aware schema.
create extension if not exists pgcrypto;
create schema if not exists crm;
create table crm.lead_source (tenant_id uuid not null, source_id uuid not null default gen_random_uuid(), code text not null check (length(btrim(code)) between 1 and 80), label text not null check (length(btrim(label)) between 1 and 200), active boolean not null default true, created_at timestamptz not null default timezone('utc', now()), primary key (tenant_id, source_id), unique (tenant_id, code));
create table crm.lead (tenant_id uuid not null, lead_id uuid not null default gen_random_uuid(), status text not null default 'new' check (status in ('new','contacted','qualified','in_progress','won','lost','archived')), person_id uuid, source_id uuid, owner_user_id text, title text not null check (length(btrim(title)) between 1 and 200), description text, close_reason text, version bigint not null default 1 check (version > 0), created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()), primary key (tenant_id, lead_id), foreign key (tenant_id, source_id) references crm.lead_source (tenant_id, source_id) on delete restrict);
create table crm.lead_status_event (tenant_id uuid not null, event_id uuid not null default gen_random_uuid(), lead_id uuid not null, from_status text, to_status text not null, actor_user_id text not null, occurred_at timestamptz not null default timezone('utc', now()), reason text, primary key (tenant_id, event_id), foreign key (tenant_id, lead_id) references crm.lead (tenant_id, lead_id) on delete restrict);
create table crm.lead_activity (tenant_id uuid not null, activity_id uuid not null default gen_random_uuid(), lead_id uuid not null, actor_user_id text not null, kind text not null check (kind in ('note','call','email','meeting','other')), notes text not null default '', occurred_at timestamptz not null default timezone('utc', now()), primary key (tenant_id, activity_id), foreign key (tenant_id, lead_id) references crm.lead (tenant_id, lead_id) on delete restrict);
create table crm.lead_assignment_event (tenant_id uuid not null, assignment_id uuid not null default gen_random_uuid(), lead_id uuid not null, from_user_id text, to_user_id text not null, actor_user_id text not null, occurred_at timestamptz not null default timezone('utc', now()), primary key (tenant_id, assignment_id), foreign key (tenant_id, lead_id) references crm.lead (tenant_id, lead_id) on delete restrict);
create table crm.lead_external_reference (tenant_id uuid not null, reference_id uuid not null default gen_random_uuid(), lead_id uuid not null, vertical_code text not null check (length(btrim(vertical_code)) between 1 and 80), external_type text not null check (length(btrim(external_type)) between 1 and 80), external_id text not null check (length(btrim(external_id)) between 1 and 200), created_at timestamptz not null default timezone('utc', now()), primary key (tenant_id, reference_id), foreign key (tenant_id, lead_id) references crm.lead (tenant_id, lead_id) on delete restrict, unique (tenant_id, vertical_code, external_type, external_id));
create table crm.lead_audit (tenant_id uuid not null, audit_id uuid not null default gen_random_uuid(), lead_id uuid, actor_user_id text not null, action text not null, occurred_at timestamptz not null default timezone('utc', now()), correlation_id text not null, outcome text not null, entity_version bigint, primary key (tenant_id, audit_id), foreign key (tenant_id, lead_id) references crm.lead (tenant_id, lead_id) on delete restrict);
create index lead_by_tenant_status on crm.lead (tenant_id, status, lead_id);
create index lead_by_tenant_owner on crm.lead (tenant_id, owner_user_id);
create index lead_by_tenant_person on crm.lead (tenant_id, person_id);
create index lead_status_event_by_lead on crm.lead_status_event (tenant_id, lead_id, occurred_at desc);
create index lead_activity_by_lead on crm.lead_activity (tenant_id, lead_id, occurred_at desc);
create index lead_assignment_by_lead on crm.lead_assignment_event (tenant_id, lead_id, occurred_at desc);
create index lead_external_reference_by_lead on crm.lead_external_reference (tenant_id, lead_id);
create index lead_audit_by_lead_time on crm.lead_audit (tenant_id, lead_id, occurred_at desc);
create or replace function crm.touch_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at = timezone('utc', now()); return new; end $$;
create or replace function crm.reject_append_only_mutation() returns trigger language plpgsql set search_path = '' as $$ begin raise exception '% is append-only', tg_table_name; end $$;
create trigger lead_touch_updated_at before update on crm.lead for each row execute function crm.touch_updated_at();
do $$ declare table_name text; begin foreach table_name in array array['lead_status_event','lead_activity','lead_assignment_event','lead_external_reference','lead_audit'] loop execute format('create trigger %I_reject_update before update on crm.%I for each row execute function crm.reject_append_only_mutation()', table_name, table_name); execute format('create trigger %I_reject_delete before delete on crm.%I for each row execute function crm.reject_append_only_mutation()', table_name, table_name); end loop; end $$;
grant usage on schema crm to authenticated;
grant select, insert, update on crm.lead_source, crm.lead to authenticated;
grant select, insert on crm.lead_status_event, crm.lead_activity, crm.lead_assignment_event, crm.lead_external_reference, crm.lead_audit to authenticated;
do $$ declare table_name text; begin foreach table_name in array array['lead_source','lead','lead_status_event','lead_activity','lead_assignment_event','lead_external_reference','lead_audit'] loop execute format('alter table crm.%I enable row level security', table_name); execute format('alter table crm.%I force row level security', table_name); execute format('create policy crm_tenant_select on crm.%I for select using (tenant_id = current_setting(''app.tenant_id'', true)::uuid)', table_name); execute format('create policy crm_tenant_insert on crm.%I for insert with check (tenant_id = current_setting(''app.tenant_id'', true)::uuid)', table_name); execute format('create policy crm_tenant_update on crm.%I for update using (tenant_id = current_setting(''app.tenant_id'', true)::uuid) with check (tenant_id = current_setting(''app.tenant_id'', true)::uuid)', table_name); end loop; end $$;
comment on schema crm is 'Tenant-aware common CRM (Leads); tenant_id is the isolation boundary.';
